begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,api,private,pg_temp;
select no_plan();
\ir fixtures/study904_analysis_fixture.sql
create temp table study904_results(k text primary key,v jsonb);
create function pg_temp.keep(p_key text,p_value jsonb) returns jsonb language plpgsql as $$begin insert into study904_results values(p_key,p_value) on conflict(k) do update set v=excluded.v;return p_value;end$$;
create function pg_temp.val(k text) returns jsonb language sql as $$select v from study904_results where study904_results.k=$1$$;
select is(private.study_analysis_config_hash('{"schemaVersion":"lca.study-analysis-config.v1","kind":"comparison","runIds":["10000000-0000-4000-8000-000000000010","10000000-0000-4000-8000-000000000011"]}'),'d6475229de0810eb5e9c7879686f589b3b3abdfafd90e8501f44b667c27b2b8d','config SHA256 exactly matches Worker golden domain/NUL/sorted compact JSON');
select ok(not private.study_analysis_config_valid(jsonb_set(pg_temp.study904_config(),'{kind}','null')),'null kind fails closed');
select ok(not private.study_analysis_config_valid(jsonb_set(pg_temp.study904_config(),'{runIds}','["90400000-0000-4000-8000-000000000012","90400000-0000-4000-8000-000000000012"]')),'duplicate/wrong cardinality is rejected');
select ok(not has_table_privilege('authenticated','private.study_analyses','SELECT') and not has_table_privilege('service_role','private.study_analyses','UPDATE'),'raw analysis actor/service access is closed');
select ok(not has_function_privilege('authenticated','api.svc_study_analysis_complete_v1(uuid,uuid,uuid,jsonb,text)','EXECUTE'),'analysis completion is service-only');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.study_analyses'::regclass),'private analyses force RLS');
select pg_temp.study894_claim(1);
select is(api.cmd_study_reporting_v1(pg_temp.study904_request('gate-off'))->>'code','CAPABILITY_UNAVAILABLE','new analysis is default off');
select is((select count(*) from private.study_analyses),0::bigint,'gate-off creates no placeholder');
update private.study_reporting_config set analysis_enabled=true;
select ok((pg_temp.keep('analysis',api.cmd_study_reporting_v1(pg_temp.study904_request('analysis-1',pg_temp.study904_config(true))))->>'ok')::boolean,'current source rights admit exact ordered same-Study comparison');
select is(api.cmd_study_reporting_v1(pg_temp.study904_request('analysis-1',pg_temp.study904_config(true))),pg_temp.val('analysis'),'exact replay recovers stable analysis/job');
select is(api.cmd_study_reporting_v1(pg_temp.study904_request('analysis-1'))->>'code','IDEMPOTENCY_CONFLICT','key cannot replace config');
select ok(not(pg_temp.val('analysis')->'data'->'value' ?| array['runIds','storageBucket','storageObjectPath']),'public record has only config Run IDs and no locators');
select is(pg_temp.val('analysis')->'data'->'value'->'factsRef','null'::jsonb,'queued analysis has no ready facts');
select is(api.cmd_study_v1(jsonb_set(pg_temp.study904_request('v2-route'),'{schemaVersion}','"lca.study-api.v2"'))->>'code','CAPABILITY_UNAVAILABLE','P1 v2 dispatch cannot negotiate analysis');
select pg_temp.study894_claim(2);
select is(api.cmd_study_reporting_v1(pg_temp.study904_request('foreign'))->>'code','FORBIDDEN','analysis identity grants no authority');
select pg_temp.study894_claim(null,null,true);
select is(private.worker_enqueue_job('study.analysis','{}')->>'code','STUDY_SCOPED_ROUTE_REQUIRED','generic enqueue cannot bypass v3 actor admission');
select ok((pg_temp.keep('claim',private.worker_claim_jobs('solver','study904-sql',1,900))->>'ok')::boolean,'canonical Worker claims the analysis');
select is(private.worker_read_job((pg_temp.val('claim')->'data'->0->>'id')::uuid,false)->>'code','STUDY_SCOPED_ROUTE_REQUIRED','generic read remains closed');
select ok((pg_temp.keep('input',api.svc_study_analysis_read_input_v1((pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,(pg_temp.val('claim')->'data'->0->>'leaseToken')::uuid))->>'ok')::boolean,'current exact lease gets Worker input seam');
select is(pg_temp.val('input')->'data'->>'schemaVersion','lca.study-analysis-input.v1','input uses exact Worker schema');
select is(pg_temp.val('input')->'data'->'runs'->0->'run'->>'runId','90400000-0000-4000-8000-000000000012','first Run preserves config order');
select is(pg_temp.val('input')->'data'->'runs'->1->'run'->>'runId','90400000-0000-4000-8000-000000000013','second Run preserves config order');
select ok(pg_temp.val('input')->'data'->'runs'->0 ?& array['run','revision','scenario','preparation','preparedArtifact','resultArtifact'],'input binds both prepared and result capabilities');
savepoint wrong_analysis_domain;
update private.worker_jobs set subject_id=gen_random_uuid() where id=(pg_temp.val('claim')->'data'->0->>'id')::uuid;
select is(api.svc_study_analysis_read_input_v1((pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,(pg_temp.val('claim')->'data'->0->>'leaseToken')::uuid)->>'code','REFERENCE_MISMATCH','matching lease and payload do not authorize a foreign canonical domain subject');
select is(api.svc_study_task_reconcile_v1('analysis',(pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,(pg_temp.val('claim')->'data'->0->>'leaseToken')::uuid,'wrong-domain-reconcile')->>'code','REFERENCE_MISMATCH','analysis upload reconciliation also binds the canonical domain subject');
select is(api.svc_study_task_fail_v1('analysis',(pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,(pg_temp.val('claim')->'data'->0->>'leaseToken')::uuid,'runtime_failed','wrong-domain-fail')->>'code','REFERENCE_MISMATCH','failure callback cannot terminalize a foreign canonical domain subject');
rollback to wrong_analysis_domain;
select is(api.svc_study_analysis_read_input_v1((pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,gen_random_uuid())->>'code','FORBIDDEN','foreign lease gets no private inputs');
savepoint source_revocation;
update public.lifecyclemodels set state_code=20 where id='89400000-0000-4000-8000-000000000101';
select is(api.svc_study_analysis_complete_v1((pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,(pg_temp.val('claim')->'data'->0->>'leaseToken')::uuid,pg_temp.study904_completion(pg_temp.val('analysis')->'data'->'value'->>'configHash'),'complete')->>'code','DISCLOSURE_DENIED','source withdrawal fences completion before artifact registration');
select ok(not exists(select 1 from private.study_artifacts where id='90400000-0000-4000-8000-000000000060'),'denied completion leaves no artifact');
rollback to source_revocation;
select ok((pg_temp.keep('completed',api.svc_study_analysis_complete_v1((pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,(pg_temp.val('claim')->'data'->0->>'leaseToken')::uuid,pg_temp.study904_completion(pg_temp.val('analysis')->'data'->'value'->>'configHash'),'complete'))->>'ok')::boolean,'leased callback atomically registers synthetic facts and terminal receipt');
select is(api.svc_study_analysis_complete_v1((pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,(pg_temp.val('claim')->'data'->0->>'leaseToken')::uuid,pg_temp.study904_completion(pg_temp.val('analysis')->'data'->'value'->>'configHash'),'complete'),pg_temp.val('completed'),'exact terminal callback replay recovers receipt');
select is(pg_temp.val('completed')->'data'->'value'->'execution'->>'status','completed','facts are ready only with completed execution');
select throws_ok('update private.study_analyses set comparability=''{}''','P0001','FROZEN_REVISION','issued analysis facts and comparability are immutable');
select pg_temp.study894_claim(1);
update private.study_reporting_config set analysis_enabled=false;
select ok((api.qry_study_reporting_v1(jsonb_build_object('schemaVersion','lca.study-api.v3','requestId','read','operation','analysis.read','analysisId',pg_temp.val('analysis')->'data'->'value'->'analysisId'))->>'ok')::boolean,'existing analysis remains readable after submission gate disabled');
select is(api.qry_study_reporting_v1(jsonb_build_object('schemaVersion','lca.study-api.v3','requestId','artifact','operation','artifact.read','studyId','89400000-0000-4000-8000-000000000010','artifactRef',pg_temp.val('completed')->'data'->'value'->'factsRef'))->>'code','CAPABILITY_UNAVAILABLE','P1 disclosure gate still controls delivery');
update private.study_runtime_config set disclosure_enabled=true;
select ok((pg_temp.keep('artifact',api.qry_study_reporting_v1(jsonb_build_object('schemaVersion','lca.study-api.v3','requestId','artifact','operation','artifact.read','studyId','89400000-0000-4000-8000-000000000010','artifactRef',pg_temp.val('completed')->'data'->'value'->'factsRef')))->>'ok')::boolean,'analysis facts gets opaque actor intent');
select pg_temp.study894_claim(null,null,true);
select ok((api.svc_study_artifact_read_resolve_v1((pg_temp.val('artifact')->'data'->>'intentId')::uuid)->>'ok')::boolean,'service resolves analysis artifact only under live original rights');
select pg_temp.study894_claim(1);
update private.study_reporting_config set analysis_enabled=true;
select pg_temp.keep('cancel-analysis',api.cmd_study_reporting_v1(pg_temp.study904_request('analysis-cancel')));
update private.study_reporting_config set analysis_enabled=false;
select ok((api.qry_study_reporting_v1(jsonb_build_object('schemaVersion','lca.study-api.v3','requestId','read-cancel','operation','task.read','studyId','89400000-0000-4000-8000-000000000010','resource',jsonb_build_object('type','analysis','id',pg_temp.val('cancel-analysis')->'data'->'value'->'analysisId')))->>'ok')::boolean,'existing analysis task remains readable with new submissions disabled');
select ok((pg_temp.keep('cancelled',api.cmd_study_reporting_v1(jsonb_build_object('schemaVersion','lca.study-api.v3','requestId','cancel','idempotencyKey','cancel','operation','task.cancel','studyId','89400000-0000-4000-8000-000000000010','resource',jsonb_build_object('type','analysis','id',pg_temp.val('cancel-analysis')->'data'->'value'->'analysisId'),'reason','Owned SQL cancellation')))->>'ok')::boolean,'scoped cancellation remains admitted when submissions are disabled');
select is(pg_temp.val('cancelled')->'data'->'value'->'execution'->>'status','cancelled','cancel uses the same canonical analysis job');
select ok((api.qry_study_reporting_v1('{"schemaVersion":"lca.study-api.v3","requestId":"caps","operation":"capability.read"}')->'data'->>'runtimeEnabled')::boolean,'read/cancel capability remains enabled independently of submission gates');
select * from finish();
rollback;
